import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3 } = ctx.THREE;

  // Root container
  const container = new Group();
  container.name = 'pricing-title-container';

  // State / Timeline tracking for cleanup
  const activeTimelines = [];
  const resourcesToDispose = [];

  // Colors from Spec
  const colorInk = '#16161d';
  const colorSurface = '#0b0b10';
  const colorAccent = '#ff2a38';
  const colorPaper = '#e8ecf2';

  // 1. Engineered Gradient Backdrop Card (representing static composition / engineered gradient surface)
  const backdropGeo = new PlaneGeometry(5.8, 2.0);
  resourcesToDispose.push(backdropGeo);

  const backdropMat = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.95
  });
  resourcesToDispose.push(backdropMat);

  // TSL shader gradient (Ink -> Surface with a sharp Accent top line)
  backdropMat.colorNode = (() => {
    const vUv = uv();
    // Convert hex values to normalized vec3
    const cInk = vec3(0.086, 0.086, 0.114);      // #16161d
    const cSurface = vec3(0.043, 0.043, 0.063);  // #0b0b10
    const cAccent = vec3(1.0, 0.165, 0.22);      // #ff2a38

    // Rich vertical background transition
    let baseMix = mix(cSurface, cInk, vUv.y);

    // Precise engineered accent line at the top edge
    const accentLine = smoothstep(0.97, 0.99, vUv.y);
    baseMix = mix(baseMix, cAccent, accentLine);

    return vec4(baseMix, 0.95);
  })();

  const backdropMesh = new Mesh(backdropGeo, backdropMat);
  backdropMesh.position.set(0, 0, -0.05);
  container.add(backdropMesh);

  // 2. Load and present the CTA Hero Isolated Image
  if (config.imageUrl) {
    const imageGeo = new PlaneGeometry(2.0, 1.25);
    resourcesToDispose.push(imageGeo);

    const imageMat = new MeshBasicNodeMaterial({
      transparent: true,
      opacity: 0
    });
    resourcesToDispose.push(imageMat);

    const imageMesh = new Mesh(imageGeo, imageMat);
    // Align to the right-hand side of the pricing title block
    imageMesh.position.set(1.6, -0.1, 0.02);
    container.add(imageMesh);

    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      imageMat.map = texture;
      imageMat.needsUpdate = true;

      const tl = gsap.to(imageMat, {
        opacity: 0.85,
        duration: 0.7,
        ease: 'power2.out'
      });
      activeTimelines.push(tl);
    });
  }

  // 3. Typography & Text Labels (Lora / JetBrains Mono hierarchy)
  // Dynamic bridging for textContent items
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const primaryText = items[0]?.text ?? "Pricing";

  // Category Tag (Mono style overlay)
  const categoryText = ctx.fontAtlas.createText('ATELIER SERVICES', {
    fontSize: 22,
    color: colorAccent,
    align: 'left'
  });
  categoryText.position.set(-2.4, 0.45, 0.05);
  container.add(categoryText);

  // Headline Title (Lora serif styled)
  const titleText = ctx.fontAtlas.createText(primaryText, {
    fontSize: 66,
    color: colorPaper,
    align: 'left'
  });
  titleText.position.set(-2.4, -0.15, 0.05);
  container.add(titleText);

  // Caption/Details Subtext
  const subtextText = ctx.fontAtlas.createText('SELECT AN AUTOMATIC TIER', {
    fontSize: 16,
    color: '#8b8b9a',
    align: 'left'
  });
  subtextText.position.set(-2.4, -0.55, 0.05);
  container.add(subtextText);

  // 4. Entrance Motion (Weighted Settle feel)
  container.position.y += 0.3;
  const entranceTl = gsap.to(container.position, {
    y: '-=0.3',
    duration: 0.9,
    ease: 'power4.out'
  });
  activeTimelines.push(entranceTl);

  // Clean-up Interface
  container.userData = {
    cleanup() {
      activeTimelines.forEach((tl) => tl.kill());
      resourcesToDispose.forEach((resource) => {
        if (resource && typeof resource.dispose === 'function') {
          resource.dispose();
        }
      });
    }
  };

  return container;
}
